def _mat_powers_gf2(M, max_t):
    """Return list P[t] = M^t over GF(2) for t = 0..max_t."""
    P = [np.eye(8, dtype=np.uint8)]
    Mm = np.mod(M.astype(np.int64), 2).astype(np.int64)
    cur = np.eye(8, dtype=np.int64)
    for _ in range(1, max_t + 1):
        cur = np.mod(Mm.dot(cur), 2)
        P.append(np.mod(cur, 2).astype(np.uint8))
    return P


def _solve_gf2(A_rows, b_vals, n_vars=8):
    """Solve A x = b over GF(2). A_rows: list of array-like length n_vars.

    Returns one solution as list of 0/1 (free variables set to 0),
    or None if the system is inconsistent.
    """
    n_eq = len(A_rows)
    # Augmented matrix as ints 0/1
    aug = [list(map(int, list(A_rows[i]))) + [int(b_vals[i])] for i in range(n_eq)]
    where = [-1] * n_vars
    row = 0
    for col in range(n_vars):
        sel = -1
        for i in range(row, n_eq):
            if aug[i][col] == 1:
                sel = i
                break
        if sel == -1:
            continue
        aug[row], aug[sel] = aug[sel], aug[row]
        where[col] = row
        for i in range(n_eq):
            if i != row and aug[i][col] == 1:
                for j in range(col, n_vars + 1):
                    aug[i][j] ^= aug[row][j]
        row += 1
    # Consistency check
    for i in range(row, n_eq):
        if all(aug[i][j] == 0 for j in range(n_vars)) and aug[i][n_vars] == 1:
            return None
        # rows within 0..row-1 are consistent by construction, but
        # also check non-pivot rows that were eliminated
    for i in range(n_eq):
        if all(aug[i][j] == 0 for j in range(n_vars)) and aug[i][n_vars] == 1:
            return None
    sol = [0] * n_vars
    for i in range(n_vars):
        if where[i] != -1:
            sol[i] = aug[where[i]][n_vars] & 1
        else:
            sol[i] = 0
    return sol


