def attack(known_pairs):
    """Recover the secret key via linear algebra over GF(2).

    Each keystream bit is a GF(2)-linear function of the 8 key bits:
    state_t = M^t key, keystream bit (byte j, position i) = row i of M^(8j+i) dot key.
    Every known pair restarts the cipher from the same key, so the byte
    index j restarts at 0 for each pair. We collect all equations and solve.
    """
    # Normalise pairs to bytes
    norm_pairs = []
    for pt, ct in known_pairs:
        if isinstance(pt, str):
            # allow hex strings just in case
            try:
                pt_b = bytes.fromhex(pt)
            except ValueError:
                pt_b = pt.encode()
        else:
            pt_b = bytes(pt)
        if isinstance(ct, str):
            try:
                ct_b = bytes.fromhex(ct)
            except ValueError:
                ct_b = ct.encode()
        else:
            ct_b = bytes(ct)
        norm_pairs.append((pt_b, ct_b))

    if not norm_pairs:
        return np.zeros(8, dtype=np.uint8)

    max_len = max(len(pt) for pt, _ in norm_pairs)
    powers = _mat_powers_gf2(_TRANSITION_MATRIX, max_len * 8)

    A_rows = []
    b_vals = []
    for pt_b, ct_b in norm_pairs:
        n = min(len(pt_b), len(ct_b))
        for j in range(n):
            ks_byte = pt_b[j] ^ ct_b[j]
            for i in range(8):
                bit = (ks_byte >> (7 - i)) & 1
                t = 8 * j + i
                row = powers[t][i, :].astype(int).tolist()
                A_rows.append(row)
                b_vals.append(bit)

    sol = _solve_gf2(A_rows, b_vals, 8) if A_rows else [0] * 8
    if sol is not None:
        key = np.array(sol, dtype=np.uint8)
        if _keystream_matches(key, norm_pairs):
            return key

    # Fallback: brute force over 256 keys (cipher has tiny key space;
    # the linear map is rank-deficient so several keys match -- any
    # matching key decrypts correctly since the keystream repeats).
    for k in range(256):
        cand = np.array([(k >> (7 - i)) & 1 for i in range(8)], dtype=np.uint8)
        if _keystream_matches(cand, norm_pairs):
            return cand
    # Last resort: return linear solution (or zeros)
    if sol is not None:
        return np.array(sol, dtype=np.uint8)
    return np.zeros(8, dtype=np.uint8)


